theme.template:
{{foreach $rows as $row}}
<li class="ipsDataItem">
    <div class="ipsDataItem_icon ipsPos_top">
        {template="userPhoto" app="core" params="$row->author(), 'mini'" group="global"}
    </div>
    <div class="ipsDataItem_main">
        <h4 class="ipsDataItem_title">
            {{if $row->hidden() === 1}}
            <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa fa-warning'></i></span></span>
            {{endif}}
            {{if $row->mapped('pinned')}}
            <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_positive" data-ipsTooltip title='{lang="pinned"}'><i class='fa fa-thumb-tack'></i></span></span>
            {{endif}}
            <a href="{$row->url()}">{$row->title}</a>
        </h4>
        <p class="ipsDataItem_meta ipsType_light ipsType_blendLinks">
            {template="rating" app="core" params="'large', $row->overall, 5" group="global"}
            <br>
            {lang="byline" htmlsprintf="$row->author()->link()"} {datetime="$row->_date"} &middot; {lang="review_comments" pluralize="$row->total_comments"}
            <p class='ipsType_normal ipsType_richText ipsType_break ipsSpacer_both'>
                {{if $row->pros}}
                <div><span class='ipsType_bold'>{lang="product_pros"}:</span> {$row->pros}</div>
                {{endif}}
                {{if $row->cons}}
                <div><span class='ipsType_bold'>{lang="product_cons"}:</span> {$row->cons}</div>
                {{endif}}
                <div data-ipsTruncate data-ipsTruncate-size="4 lines" data-ipsTruncate-type="remove">
                    {$row->truncated( true )|raw}
                </div>
                <a href="{$row->url()}">{lang="read_more"}</a>
            </p>
        </p>
    </div>
</li>
{{endforeach}}

{{if $condensed}}

{template="rating" app="core" params="'small', $product->averageRating(), 5" group="global"}
<br>
{{if $image = $product->image}}
<a href="{$product->url()}"><img src='{file="$product->image" extension="reviews_Product"}' class="cProductImage_thumb"></a>
{{endif}}

{{else}}

<div class="ipsColumns ipsColumns_collapsePhone">
    <div class="ipsColumn ipsColumn_wide">
        <div class="ipsBox ipsPad_half">
            {{if $product->image}}
            <div class="ipsType_center">
                <a href="{$product->url()}"><img src='{file="$product->image" extension="reviews_Product"}' class="cProductImage_thumb"></a>
            </div>
            {{endif}}
        </div>
    </div>
    <div class="ipsColumn ipsColumn_fluid">
        <h3 class="ipsType_large"><a href="{$product->url()}">{$product->name}</a></h3>
        {template="rating" app="core" params="'medium', $product->averageRating(), 5" group="global"}
        <div class="ipsType_richText ipsType_break ipsContained ipsType_normal">
            <div data-ipsTruncate data-ipsTruncate-size="4 lines" data-ipsTruncate-type="remove">
                {$product->truncated( true )|raw}
            </div>
        </div>
    </div>
</div>

{{endif}}

{{if $condensed}}

{template="rating" app="core" params="'small', $review->overall, 5" group="global"}

{{else}}

<div class="ipsColumns ipsColumns_collapsePhone">
    {{$product = $review->product();}}
    <div class="ipsColumn ipsColumn_wide">
        <div class="ipsBox ipsPad_half">
            <div class="ipsType_light">{lang="review_of_product"}</div>
            <h2 class="ipsType_large"><a href="{$product->url()}">{$product->name}</a></h2>
            {{if $product->image}}
            <div class="ipsType_center">
                <a href="{$product->url()}"><img src='{file="$product->image" extension="reviews_Product"}' class="cProductImage_thumb"></a>
            </div>
            {{endif}}
        </div>
    </div>
    <div class="ipsColumn ipsColumn_fluid">
        <h3 class="ipsType_large"><a href="{$review->url()}">{$review->title}</a></h3>
        {template="rating" app="core" params="'medium', $review->overall, 5" group="global"}
        <div class="ipsType_richText ipsType_break ipsContained ipsType_normal">
            {{if $review->pros}}
            <div><span class="ipsType_bold">{lang="review_pros"}:</span> {$review->pros}</div>
            {{endif}}
            {{if $review->cons}}
            <div><span class="ipsType_bold">{lang="review_cons"}:</span> {$review->cons}</div>
            {{endif}}
            <div data-ipsTruncate data-ipsTruncate-size="4 lines" data-ipsTruncate-type="remove">
                {$review->truncated( true )|raw}
            </div>
        </div>
    </div>
</div>

{{endif}}

{{if \is_array( $ratings ) && \count( $ratings )}}
<div class="ipsBox ipsSpacer_top ipsPad_half ipsType_left">
    <h3 class="ipsType_minorHeading">{lang="detailed_ratings"}</h3>
    {{foreach $ratings as $name => $score}}
    <div class="ipsClearfix">
        <div class="ipsPos_left ipsType_light">{$name}</div>
        <div class="ipsPos_right">
            {template="rating" app="core" group="global" params="'medium', $score"}
        </div>
    </div>
    {{endforeach}}
</div>
{{endif}}

{{foreach $rows as $row}}
<div class="ipsSpacer_both cReviewRow ipsPad_half {{if $row->hidden()}}ipsModerated{{endif}}">
    <div class="ipsPhotoPanel ipsPhotoPanel_mini ipsPhotoPanel_notPhone">
        {template="userPhoto" app="core" params="$row->author(), 'mini'" group="global"}
        <div>
            <h2 class="ipsType_sectionHead ipsType_blendLinks ipsContained_container">
                {{if $row->hidden() === 1}}
                <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa fa-warning'></i></span></span>
                {{elseif $row->hidden()}}
                <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="review_hidden"}'><i class='fa fa-eye-slash'></i></span></span>
                {{endif}}
                <a href="{$row->url()}">{$row->title}</a>
            </h2>
            <p class='ipsType_light ipsType_reset ipsType_blendLinks'>
                {template="rating" app="core" params="'large', $row->overall, 5" group="global"}
                <br>
                {lang="byline" htmlsprintf="$row->author()->link()"} {datetime="$row->_date"} &middot; {lang="review_comments" pluralize="$row->total_comments"}
            </p>
        </div>
    </div>
    <section class='ipsType_normal ipsType_richText ipsType_break ipsSpacer_both'>
        {{if $row->pros}}
        <div><span class='ipsType_bold'>{lang="product_pros"}:</span> {$row->pros}</div>
        {{endif}}
        {{if $row->cons}}
        <div><span class='ipsType_bold'>{lang="product_cons"}:</span> {$row->cons}</div>
        {{endif}}
        <div data-ipsTruncate data-ipsTruncate-size="6 lines" data-ipsTruncate-type="remove">
        {$row->truncated( true )|raw}
        </div>
        <a href="{$row->url()}">{lang="read_more"}</a>
    </section>
    {{if $row->can( 'moderate' )}}
    <ul class="ipsList_inline ipsType_blendLinks ipsType_small">
        <li>
            <a href="{$row->url( 'edit' )}"><i class='fa fa-edit'></i> {lang="edit"}</a>
        </li>
        {{if $row->canHide()}}
        <li>
            <a href="{$row->url()->csrf()->setQueryString( array( 'do' => 'moderate', 'action' => 'hide' ) )}"><i class='fa fa-minus'></i> {lang="hide"}</a>
        </li>
        {{endif}}
        {{if $row->canUnhide()}}
        <li>
            <a href="{$row->url()->csrf()->setQueryString( array( 'do' => 'moderate', 'action' => 'unhide' ) )}"><i class='fa fa-check'></i> {lang="unhide"}</a>
        </li>
        {{endif}}
        {{if $row->canMove()}}
        <li>
            <a href="{$row->url()->csrf()->setQueryString( 'do', 'move' )}" data-ipsDialog data-ipsDialog-title='{lang="move_review"}' data-ipsDialog-size="narrow"><i class='fa fa-arrow-right'></i> {lang="move"}</a>
        </li>
        {{endif}}
    </ul>
    {{endif}}
</div>
{{endforeach}}

{{$product = $review->product();}}
<div class="ipsPageHeader ipsClearfix">
    <div class="ipsPos_left">
        <div class="ipsType_large ipsType_light">{$product->container()->_title}</div>
        <div class="ipsType_pageTitle">
            {{if $review->hidden() == 1}}
            <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa fa-warning'></i></span></span>
            {{elseif $review->hidden()}}
            <span><span class="ipsBadge ipsBadge_icon ipsBadge_small ipsBadge_warning" data-ipsTooltip title='{lang="review_hidden"}'><i class='fa fa-eye-slash'></i></span></span>
            {{endif}}
            {$review->title}
        </div>
    </div>
    {{if $review->can( 'moderate' )}}
    <ul class="ipsToolList ipsToolList_horizontal">
        <li>
            <a href="#elReviewMenu_menu" id="elReviewMenu" data-ipsMenu class="ipsButton ipsButton_important ipsButton_verySmall">{lang="moderate_review"} <i class="fa fa-caret-down"></i></a>
        </li>
    </ul>
    <ul id="elReviewMenu_menu" class="ipsMenu ipsMenu_auto ipsHide">
        <li class="ipsMenu_item">
            <a href="{$review->url( 'edit' )}">{lang="edit_review"}</a>
        </li>
        {{if $review->canHide()}}
        <li class="ipsMenu_item">
            <a href="{$review->url()->csrf()->setQueryString( array( 'do' => 'moderate', 'action' => 'hide' ) )}">{lang="hide_review"}</a>
        </li>
        {{endif}}
        {{if $review->canUnhide()}}
        <li class="ipsMenu_item">
            <a href="{$review->url()->csrf()->setQueryString( array( 'do' => 'moderate', 'action' => 'unhide' ) )}">{lang="unhide_review"}</a>
        </li>
        {{endif}}
        {{if $review->canMove()}}
        <li class="ipsMenu_item">
            <a href="{$review->url()->csrf()->setQueryString( 'do', 'move' )}" data-ipsDialog data-ipsDialog-title='{lang="move_review"}' data-ipsDialog-size="narrow">{lang="move_review"}</a>
        </li>
        {{endif}}
        {{if $review->canDelete()}}
        <li class="ipsMenu_item">
            <a href="{$review->url()->csrf()->setQueryString( array( 'do' => 'moderate', 'action' => 'delete' ) )}" data-confirm>{lang="delete_review"}</a>
        </li>
        {{endif}}
    </ul>
    {{elseif $review->canEdit()}}
    <ul class="ipsToolList ipsToolList_horizontal">
        <li>
            <a href="{$review->url( 'edit' )}" class="ipsButton ipsButton_important ipsButton_verySmall">{lang="edit_review"}</a>
        </li>
    </ul>
    {{endif}}
    <div class="ipsPos_right">
        {template="follow" app="core" group="global" params="'reviews', 'review', $review->id, $review->followersCount()"}
    </div>
</div>
<div class="ipsColumns ipsColumns_collapsePhone">
    <div class="ipsColumn ipsColumn_medium">
        {template="productBox" app="reviews" group="review" params="$review, $product"}
    </div>
    <div class="ipsColumn ipsColumn_fluid">
        <div class="ipsPhotoPanel ipsPhotoPanel_mini ipsPhotoPanel_notPhone">
            {template="userPhoto" app="core" params="$review->author(), 'mini'" group="global"}
            <div>
                <p class='ipsType_light ipsType_reset ipsType_blendLinks'>
                    {template="rating" app="core" params="'large', $review->overall, 5" group="global"}
                    <br>
                    {lang="byline" htmlsprintf="$review->author()->link()"} {datetime="$review->_date"} &middot; {lang="review_views" pluralize="$review->views"} &middot; {lang="review_comments" pluralize="$review->total_comments"}
                </p>
            </div>
        </div>
        <div class="ipsType_richText ipsType_break ipsContained ipsType_normal">
            {{if $review->pros}}
            <div><span class="ipsType_bold">{lang="review_pros"}:</span> {$review->pros}</div>
            {{endif}}
            {{if $review->cons}}
            <div><span class="ipsType_bold">{lang="review_cons"}:</span> {$review->cons}</div>
            {{endif}}
            <div class="ipsSpacer_top cReviewContent">
                {$review->content|raw}
            </div>
        </div>
    </div>
</div>
<section class="ipsSpacer_top">
    {template="comments" app="reviews" group="review" params="$review"}
</section>

theme.css:
.cCategoryLevel1 {
    margin-left: 15px;
}

.cProductImage {
    max-width: 100%;
}

.cProduct_ratingZero {
    opacity: 0.4;
}

.cProduct_ratingRow .ipsProgressBar {
    height: 12px;
    margin-top: 3px;
    background: #eee;
}

    .cProduct_ratingRow .ipsProgressBar .ipsProgressBar_progress {
        background: #999;
    }

.cReviewRow {
    border-width: 0 0 1px 0;
    border-style: solid;
    border-color: #ebebeb;
}

.cProductImage_thumb {
    max-width: 160px;
}

.cReviewContent img {
    max-width: 450px !important;
    max-height: 800px !important;
}
